import { CosmosClient, Container } from '@azure/cosmos';
import { DefaultAzureCredential } from '@azure/identity';
import { Injectable, Scope } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';

@Injectable({ scope: Scope.DEFAULT }) // Explicitly DEFAULT scope = Singleton
export class CosmosDatabaseService {
  private static instanceCount = 0;

  private static singletonInstance: CosmosDatabaseService | undefined;

  /**
   * Get the number of times this service was instantiated
   * Should always return 1 in production
   * @returns The number of times the service was instantiated
   */
  public static getInstanceCount(): number {
    return CosmosDatabaseService.instanceCount;
  }

  /**
   * Validate that only one instance exists
   * @throws Error if multiple instances detected
   */
  public static validateSingleton(): void {
    if (CosmosDatabaseService.instanceCount !== 1) {
      throw new Error(
        `â CosmosDatabaseService singleton violation! Instance count: ${CosmosDatabaseService.instanceCount}`,
      );
    }
  }

  private readonly client: CosmosClient;

  private readonly containerJobsDefinition: Container;

  private readonly containerJobsExecutionsHistory: Container;

  public constructor(private readonly configService: ConfigService) {
    // Singleton validation - should only be called once
    CosmosDatabaseService.instanceCount += 1;
    if (CosmosDatabaseService.singletonInstance) {
      // Copy references from existing instance
      this.client = CosmosDatabaseService.singletonInstance.client;
      this.containerJobsDefinition =
        CosmosDatabaseService.singletonInstance.containerJobsDefinition;
      this.containerJobsExecutionsHistory =
        CosmosDatabaseService.singletonInstance.containerJobsExecutionsHistory;
      return;
    }

    const credential = new DefaultAzureCredential();

    this.client = new CosmosClient({
      aadCredentials: credential,
      endpoint: this.cosmosDbEndpoint,
    });

    this.containerJobsExecutionsHistory = this.client
      .database(this.cosmosDbDatabase)
      .container(this.cosmosDbContainerJobsExecutionsHistory);

    this.containerJobsDefinition = this.client
      .database(this.cosmosDbDatabase)
      .container(this.cosmosDbContainerJobsDefinition);
    // Store as singleton
    CosmosDatabaseService.singletonInstance = this;
  }

  // A method to return the container for reuse in other services
  public get getContainerJobsExecutionsHistory(): Container {
    return this.containerJobsExecutionsHistory;
  }

  public get getContainerJobsDefinition(): Container {
    return this.containerJobsDefinition;
  }

  public get cosmosDbEndpoint(): string {
    return (
      this.configService.get<string>('cosmosDbEndpoint') ??
      'https://cosmos-gptmpxn01-eun-dev-core-01.documents.azure.com:443/'
    );
  }

  public get cosmosDbDatabase(): string {
    return this.configService.get<string>('cosmosDbDatabase') ?? 'Mes';
  }

  public get cosmosDbContainerJobsDefinition(): string {
    return (
      this.configService.get<string>('cosmosDbContainerJobsDefinition') ??
      'JobSchedulerDefinitions'
    );
  }

  public get cosmosDbContainerJobsExecutionsHistory(): string {
    return (
      this.configService.get<string>(
        'cosmosDbContainerJobsExecutionsHistory',
      ) ?? 'JobExecutionHistory'
    );
  }

  /**
   * Get diagnostic information about the service
   * @returns Diagnostic information object
   */
  public getDiagnostics(): Record<string, unknown> {
    return {
      containers: {
        definitions: this.cosmosDbContainerJobsDefinition,
        history: this.cosmosDbContainerJobsExecutionsHistory,
      },
      database: this.cosmosDbDatabase,
      endpoint: this.cosmosDbEndpoint,
      instanceCount: CosmosDatabaseService.instanceCount,
      isSingleton:
        CosmosDatabaseService.singletonInstance === this &&
        CosmosDatabaseService.instanceCount === 1,
    };
  }
}

