import { ValidationPipe, Logger } from '@nestjs/common';
import { ModuleRef, NestFactory } from '@nestjs/core';
import type { NestExpressApplication } from '@nestjs/platform-express';
import * as express from 'express';
import { bootstrapActors } from './reminder/actor/reminder-actor.bootstrap';
import { AppModule } from '@/app.module';

/**
 * Bootstrap the NestJS application
 */
async function bootstrap(): Promise<void> {
  const app = await NestFactory.create<NestExpressApplication>(AppModule, {
    rawBody: true,
  });

  app.use(express.json({ type: 'application/cloudevents+json' }));
  app.use(express.json({ type: 'application/json' }));
  // Global validation pipe
  app.useGlobalPipes(
    new ValidationPipe({
      forbidNonWhitelisted: true,
      transform: true,
      whitelist: true,
    }),
  );

  app.enableCors({
    allowedHeaders: 'Content-Type,Authorization',
    origin: '*',
  });

  const moduleReference = app.get(ModuleRef);
  await bootstrapActors(moduleReference);
  // Graceful shutdown handlers
  const logger = new Logger('Bootstrap');
  const shutdown = async (signal: string): Promise<void> => {
    logger.log(`${signal} received, starting graceful shutdown...`);

    try {
      // Clean up actor service locator resources
      const actorServiceLocator = await import(
        './reminder/actor/services/actor-service-locator'
      );
      await actorServiceLocator.ActorServiceLocator.cleanup();

      // Close the NestJS application
      await app.close();
      logger.log('Application closed successfully');
    } catch (error) {
      logger.error('Error during shutdown:', error);
      throw error;
    }
  };

  process.on('SIGTERM', () => {
    shutdown('SIGTERM').catch((error) => {
      logger.error('SIGTERM handler error:', error);
    });
  });
  process.on('SIGINT', () => {
    shutdown('SIGINT').catch((error) => {
      logger.error('SIGINT handler error:', error);
    });
  });
}

bootstrap();

