@Module({
  imports: [AppLoggerModule, ReminderSchedulerModule],
})
export class ReminderActorModule {}

import { DaprClient } from '@dapr/dapr';
import { Logger } from '@nestjs/common';
import { ModuleRef } from '@nestjs/core';
import { AppLogger } from '@/common/logger/app-logger';
import { CosmosDatabaseService } from '@/config/cosmos-db/cosmos-database.service';

export class ActorServiceLocator {
  private static instance: ActorServiceLocator;

  private static moduleRef: ModuleRef;

  private static daprClient: DaprClient | undefined = undefined;

  // Cache the container service to ensure same instance is always returned
  private static cachedContainerService: CosmosDatabaseService | undefined =
    undefined;

  public static getInstance(): ActorServiceLocator {
    if (!ActorServiceLocator.instance) {
      ActorServiceLocator.instance = new ActorServiceLocator();
    }
    return ActorServiceLocator.instance;
  }

  public static initializeWithModuleRef(moduleReference: ModuleRef): void {
    ActorServiceLocator.moduleRef = moduleReference;
  }

  public static async cleanup(): Promise<void> {
    const logger = new Logger(ActorServiceLocator.name);
    if (ActorServiceLocator.daprClient) {
      // DaprClient doesn't have explicit close method, but we clear the reference
      // To allow garbage collection
      ActorServiceLocator.daprClient = undefined;
      logger.log('DaprClient reference cleared');
    }

    // Clear cached container service
    if (ActorServiceLocator.cachedContainerService) {
      ActorServiceLocator.cachedContainerService = undefined;
      logger.log('Cached container service cleared');
    }

    logger.log('ActorServiceLocator cleanup completed');
  }

  public static getDaprClient(): DaprClient {
    ActorServiceLocator.daprClient ??= new DaprClient();
    return ActorServiceLocator.daprClient;
  }

  private readonly loger: Logger = new Logger(ActorServiceLocator.name);

  private constructor() {}

  public getAppLogger(): AppLogger {
    if (!ActorServiceLocator.moduleRef) {
      this.loger.error('ActorServiceLocator not initialized with ModuleRef');
      throw new Error('ActorServiceLocator not initialized with ModuleRef');
    }
    return ActorServiceLocator.moduleRef.get(AppLogger, { strict: false });
  }

  public getContainer(): CosmosDatabaseService {
    if (!ActorServiceLocator.moduleRef) {
      this.loger.error('ActorServiceLocator not initialized with ModuleRef');
      throw new Error('ActorServiceLocator not initialized with ModuleRef');
    }

    // Return cached instance if available to ensure singleton
    if (ActorServiceLocator.cachedContainerService) {
      return ActorServiceLocator.cachedContainerService;
    }

    // Get service from DI container (should be singleton)
    const service = ActorServiceLocator.moduleRef.get(CosmosDatabaseService, {
      strict: false,
    });

    // Cache it for subsequent calls
    ActorServiceLocator.cachedContainerService = service;
    // Validate singleton
    try {
      CosmosDatabaseService.validateSingleton();
    } catch (error) {
      this.loger.error(
        `â Singleton validation failed: ${error.message}`,
        error.stack,
      );
    }

    return service;
  }
}

import * as cronParser from 'cron-parser';

/**
 * Utility class for parsing job-related time formats, ISO strings, and cron expressions.
 * All methods are static and stateless â safe to use anywhere in your scheduler logic.
 */
export class JobTimeParserHelper {
  /**
   * Try to parse ISO string as a date
   * @param iso ISO string to parse
   * @returns seconds from now or undefined if not a valid date
   */
  public static tryParseAsDate(iso: string): number | undefined {
    const now = Date.now();
    const date = Date.parse(iso);
    if (!Number.isNaN(date)) {
      return Math.max(0, Math.floor((date - now) / 1000));
    }
    return undefined;
  }

  /**
   * Parse the date part of ISO 8601 duration (years, months, weeks, days)
   * @param iso ISO duration string
   * @returns object with seconds and hasDuration flag
   */
  public static parseDatePart(iso: string): {
    hasDuration: boolean;
    seconds: number;
  } {
    let totalSeconds = 0;
    let hasDuration = false;

    // Extract years
    const yearsRegex = /P(\d+)Y/;
    const yearsMatch = yearsRegex.exec(iso);
    if (yearsMatch) {
      const years = Number.parseInt(yearsMatch[1], 10);
      totalSeconds += years * 365 * 24 * 60 * 60; // Approximate
      hasDuration = true;
    }

    // Extract months
    const monthsRegex = /P(?:\d+Y)?(\d+)M(?!\D)/;
    const monthsMatch = monthsRegex.exec(iso);
    if (monthsMatch) {
      const months = Number.parseInt(monthsMatch[1], 10);
      totalSeconds += months * 30 * 24 * 60 * 60; // Approximate
      hasDuration = true;
    }

    // Extract weeks
    const weeksRegex = /P(?:\d+Y)?(?:\d+M)?(\d+)W/;
    const weeksMatch = weeksRegex.exec(iso);
    if (weeksMatch) {
      const weeks = Number.parseInt(weeksMatch[1], 10);
      totalSeconds += weeks * 7 * 24 * 60 * 60;
      hasDuration = true;
    }

    // Extract days
    const daysRegex = /P(?:\d+Y)?(?:\d+M)?(?:\d+W)?(\d+)D/;
    const daysMatch = daysRegex.exec(iso);
    if (daysMatch) {
      const days = Number.parseInt(daysMatch[1], 10);
      totalSeconds += days * 24 * 60 * 60;
      hasDuration = true;
    }

    return { hasDuration, seconds: totalSeconds };
  }

  /**
   * Parse the time part of ISO 8601 duration (hours, minutes, seconds)
   * @param iso ISO duration string
   * @returns object with seconds and hasDuration flag
   */
  public static parseTimePart(iso: string): {
    hasDuration: boolean;
    seconds: number;
  } {
    let totalSeconds = 0;
    let hasDuration = false;

    // Extract hours
    const hoursRegex = /T(\d+)H/;
    const hoursMatch = hoursRegex.exec(iso);
    if (hoursMatch) {
      const hours = Number.parseInt(hoursMatch[1], 10);
      totalSeconds += hours * 60 * 60;
      hasDuration = true;
    }

    // Extract minutes - must not be part of seconds (e.g., 1M30S)
    const minutesRegex = /T(?:\d+H)?(\d+)M(?!\D)/;
    const minutesMatch = minutesRegex.exec(iso);
    if (minutesMatch) {
      const minutes = Number.parseInt(minutesMatch[1], 10);
      totalSeconds += minutes * 60;
      hasDuration = true;
    }

    // Extract seconds
    const secondsRegex = /T(?:\d+H)?(?:\d+M)?(\d+(?:\.\d+)?)S/;
    const secondsMatch = secondsRegex.exec(iso);
    if (secondsMatch) {
      const seconds = Math.floor(Number.parseFloat(secondsMatch[1]));
      totalSeconds += seconds;
      hasDuration = true;
    }

    return { hasDuration, seconds: totalSeconds };
  }

  /**
   * Parse ISO 8601 duration string
   * @param iso Duration string starting with 'P'
   * @returns total seconds or undefined if parsing failed
   */
  public static parseDurationString(iso: string): number | undefined {
    let totalSeconds = 0;
    let hasDuration = false;

    // Parse date part (before T)
    const datePart = this.parseDatePart(iso);
    totalSeconds += datePart.seconds;
    hasDuration = hasDuration || datePart.hasDuration;

    // Parse time part (after T)
    if (iso.includes('T')) {
      const timePart = this.parseTimePart(iso);
      totalSeconds += timePart.seconds;
      hasDuration = hasDuration || timePart.hasDuration;
    }

    if (hasDuration) {
      return Math.max(0, totalSeconds);
    }

    return undefined;
  }

  /**
   * Check if cron expression has specific day-of-month restrictions
   * @param cronExpression The cron expression to check
   * @returns true if it has day-of-month restrictions
   */
  public static hasSpecificDayOfMonth(cronExpression: string): boolean {
    const parts = cronExpression.trim().split(/\s+/);
    const dayOfMonthField = parts.length === 5 ? parts[2] : parts[3]; // Adjust for 5 vs 6 field format

    // Check if day-of-month field is not a wildcard
    return dayOfMonthField !== '*' && dayOfMonthField !== '?';
  }

  /**
   * Determines whether a cron expression should execute at the given reference date,
   * considering a specified tolerance in milliseconds.
   * @param cronExpr - The cron expression to evaluate.
   * @param referenceDate - The date to use as the reference point for execution (defaults to current date).
   * @param toleranceMs - The allowed tolerance in milliseconds for execution (defaults to 1000ms).
   * @returns `boolean` - Returns `true` if the cron expression is scheduled to execute within the tolerance window, otherwise `false`.
   */
  public static shouldExecuteBasedOnCron(
    cronExpr: string,
    referenceDate = new Date(),
    toleranceMs = 1000,
  ): boolean {
    try {
      const interval = cronParser.CronExpressionParser.parse(cronExpr, {
        currentDate: referenceDate,
      });
      const nextExecution = interval.next();
      const diff = nextExecution.getTime() - referenceDate.getTime();
      return diff >= 0 && diff <= toleranceMs;
    } catch {
      return false;
    }
  }

  /**
   * Converts ISO8601 duration or date string to seconds.
   * Improved implementation with better parsing and logging
   * @param iso The ISO8601 duration or date string
   * @returns Number of seconds
   */
  public static isoToSeconds(iso: string): number {
    if (!iso) {
      return 0;
    }

    try {
      // If ISO is a date, convert to seconds from now
      const dateSeconds = this.tryParseAsDate(iso);
      if (dateSeconds !== undefined) {
        return dateSeconds;
      }

      // If ISO is a duration, parse it
      if (iso.startsWith('P')) {
        const durationSeconds = this.parseDurationString(iso);
        if (durationSeconds !== undefined) {
          return durationSeconds;
        }
      }

      // Handle simplified formats for direct parsing
      const simpleFormatSeconds = this.parseSimpleFormats(iso);
      if (simpleFormatSeconds !== undefined) {
        return simpleFormatSeconds;
      }

      return 900; // Default to 15 minutes
    } catch {
      return 900; // Default to 15 minutes on error
    }
  }

  /**
   * Parse simple format ISO strings
   * @param iso ISO string to parse
   * @returns seconds or undefined if not a simple format
   */
  public static parseSimpleFormats(iso: string): number | undefined {
    // PT format for hours, minutes, seconds
    const hoursRegex = /^PT(\d+)H$/;
    const minutesRegex = /^PT(\d+)M$/;
    const secondsRegex = /^PT(\d+)S$/;

    const ptFormatMatches = {
      hours: hoursRegex.exec(iso),
      minutes: minutesRegex.exec(iso),
      seconds: secondsRegex.exec(iso),
    };

    if (ptFormatMatches.seconds) {
      const seconds = Number.parseInt(ptFormatMatches.seconds[1], 10);
      return Math.max(0, seconds);
    }

    if (ptFormatMatches.minutes) {
      const minutes = Number.parseInt(ptFormatMatches.minutes[1], 10);
      return Math.max(0, minutes * 60);
    }

    if (ptFormatMatches.hours) {
      const hours = Number.parseInt(ptFormatMatches.hours[1], 10);
      return Math.max(0, hours * 3600);
    }

    // P format for days
    const pDaysRegex = /^P(\d+)D$/;
    const pDaysMatch = pDaysRegex.exec(iso);
    if (pDaysMatch) {
      const days = Number.parseInt(pDaysMatch[1], 10);
      return Math.max(1, days * 86_400);
    }

    return undefined;
  }
}

// ReminderActorService implements a minimal Dapr actor for reminders.
import { AbstractActor, Temporal, HttpMethod, DaprClient } from '@dapr/dapr';
import { JobsLogContext } from '@mesx/common-lib';
import { AppLogger } from '../../../common/logger/app-logger';
import { parseCronExpression } from '../../scheduler/utils/cron-utils';
import { JobData } from '../interfaces/job-data.interface';
import { ReminderJob } from '../interfaces/reminder-job.interface';
import { ActorReminderInterface } from '../interfaces/reminder.interface';
import { logJobExecution } from '../utils/cosmos-database.util';
import { parseJobData } from '../utils/job-data-parser';
import { ActorServiceLocator } from './actor-service-locator';
import { JobTimeParserHelper } from './job-time-parser.helper';
import { asyncTryCatch } from '@/common/utils/async-try-catch';
import { CosmosDatabaseService } from '@/config/cosmos-db/cosmos-database.service';

// Basic interface for job data to avoid using 'any'

export class JobActor extends AbstractActor implements ActorReminderInterface {
  private static appLogger(): AppLogger {
    return ActorServiceLocator.getInstance().getAppLogger();
  }

  private static getContainer(): CosmosDatabaseService {
    return ActorServiceLocator.getInstance().getContainer();
  }

  private static getDaprClient(): DaprClient {
    return ActorServiceLocator.getDaprClient();
  }

  private readonly prefix = 'executeJobImmediately_';

  public async receiveReminder(data: string): Promise<void> {
    const context: JobsLogContext = {
      method: 'receiveReminder',
      service: 'JobActor',
    };
    const job = parseJobData(data, JobActor.appLogger());
    if (!job?.jobId) return;

    const cronExpression =
      job.payload.plant?.schedule?.cronExpression ??
      job.payload.defaultSchedule?.cronExpression;

    if (
      cronExpression &&
      !JobTimeParserHelper.shouldExecuteBasedOnCron(cronExpression)
    ) {
      JobActor.appLogger().debug(
        `[ReminderActor] Skipping job ${job.jobId} - current time does not match cron schedule: ${cronExpression}`,
        context,
      );
      return;
    }

    const [, error] = await asyncTryCatch(() => this.processJob(job));
    if (error) {
      JobActor.appLogger().error(
        `[ReminderActor] Error processing job ${job.jobId}: ${error}`,
        context,
        error,
      );
    }
  }

  /**
   * Process a job from a reminder
   * @param job The job to process
   */
  private async processJob(job: ReminderJob): Promise<void> {
    const context: JobsLogContext = {
      method: 'processJob',
      service: 'JobActor',
    };
    const startTime = Date.now();
    let duration = 0;
    let status: 'success' | 'failure' = 'failure';
    let statusCode = 500;
    let responseBody: Record<string, unknown> | undefined;
    let errorMessage: string | null = null;
    try {
      const { id, service, appId, path, plant } = job.payload;

      if (!id || !service || !appId || !path) {
        return;
      }
      if (job.jobId && plant) {
        await this.updateJobState(job.jobId, String(plant.id), 'running');
      }
      // Build the API path with plant parameter replacement
      let apiPath = path;
      if (plant) {
        // Replace any placeholder with the actual plant ID and resource
        apiPath = apiPath
          .replaceAll(':plant', plant.id.toString())
          .replaceAll('$plant', plant.id.toString());

        // Replace resource placeholder if it exists in the path and params
        if (
          plant.params?.resource &&
          typeof plant.params?.resource === 'string'
        ) {
          apiPath = apiPath
            .replaceAll(':resource', plant.params?.resource.toString())
            .replaceAll('$resource', plant.params?.resource.toString());
        }
        if (plant.params?.additionalProperties) {
          for (const [key, value] of Object.entries(
            plant.params.additionalProperties,
          )) {
            if (typeof value === 'string' || typeof value === 'number') {
              apiPath = apiPath
                .replaceAll(`:${key}`, value.toString())
                .replaceAll(`$${key}`, value.toString());
            }
          }
        }
      }
      const response = await JobActor.getDaprClient().invoker.invoke(
        appId,
        apiPath,
        HttpMethod.POST,
        plant?.params ?? {},
      );
      duration = Date.now() - startTime;
      status = 'success';
      statusCode = 200; // Dapr client doesn't expose status code directly
      responseBody = response
        ? (response as Record<string, unknown>)
        : { success: true };
    } catch (error) {
      // Calculate execution duration
      duration = Date.now() - startTime;
      status = 'failure';
      statusCode = error?.statusCode ?? 500;
      errorMessage = error?.message ?? 'Unknown error';
    } finally {
      if (job.jobId && job.payload.plant?.id) {
        await this.updateJobState(
          job.jobId,
          String(job.payload.plant?.id),
          'active',
        );
      }
      const [, loggingError] = await asyncTryCatch(() =>
        logJobExecution(
          job,
          duration,
          status,
          statusCode,
          JobActor.appLogger(),
          responseBody,
          errorMessage,
        ),
      );
      if (loggingError) {
        JobActor.appLogger().error(
          `[ReminderActor] Failed to log execution history: ${loggingError}`,
          context,
        );
      }
    }
  }

  /**
   * Arms a reminder with the specified job, due time, and period
   * @param reminderName Unique name for the reminder
   * @param job Job data for the reminder
   * @param dueTimeIso ISO string for when the reminder should first trigger
   * @param periodIso ISO string for the period between reminder triggers (recurring)
   */
  public async armReminder(
    reminderName: string,
    job: ReminderJob,
    dueTimeIso: string,
    periodIso?: string,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'armReminder',
      service: 'JobActor',
    };
    try {
      await super.unregisterActorReminder(reminderName).catch(() => {
        JobActor.appLogger().debug(
          `[ReminderActorService] No existing reminder to unregister or unregister failed`,
          context,
        );
      });
    } catch (error) {
      JobActor.appLogger().log(
        `[ReminderActorService] Error while trying to unregister existing reminder: ${error}`,
        context,
      );
      // Continue anyway since this is just a precaution
    }

    // Handle null or undefined dueTimeIso by defaulting to immediate execution
    const dueSeconds = dueTimeIso
      ? JobTimeParserHelper.isoToSeconds(dueTimeIso)
      : 0;

    // For period, ensure it's at least 60 seconds if specified (avoid too frequent execution)
    const periodSeconds = periodIso
      ? JobTimeParserHelper.isoToSeconds(periodIso)
      : 0;
    try {
      // Convert the job to a JSON string before passing it to the reminder
      // This ensures proper serialization and deserialization
      const jobData = JSON.stringify(job);
      // Register the reminder with the calculated values
      await super.registerActorReminder(
        reminderName,
        Temporal.Duration.from({ seconds: dueSeconds }),
        periodSeconds > 0
          ? Temporal.Duration.from({ seconds: periodSeconds })
          : undefined, // Use undefined for one-time reminders
        undefined,
        jobData,
      );
    } catch (error) {
      JobActor.appLogger().error(
        `[ReminderActorService] Error registering reminder ${reminderName}: ${error}`,
        context,
      );
      throw error;
    }
  }

  public async disarmReminder(reminderName: string): Promise<void> {
    const context: JobsLogContext = {
      method: 'disarmReminder',
      service: 'JobActor',
    };
    try {
      await super.unregisterActorReminder(reminderName);
    } catch (error) {
      JobActor.appLogger().error(
        `[ReminderActorService] Error unregistering reminder ${reminderName}: ${error}`,
        context,
      );
      throw error;
    }
  }

  public async getState<T = unknown>(key: string): Promise<T | null> {
    const result = await this.getStateManager().getState(key);
    return (result as T) ?? null;
  }

  public async setState<T>(key: string, value: T): Promise<void> {
    await this.getStateManager().setState(key, value);
    await this.getStateManager().saveState();
  }

  /**
   * Activate a job by setting up a reminder
   * For required jobs, this activates all plants at once
   * For onDemand jobs, this activates a specific plant
   * @param data The data containing job information
   * @param data.job The job to activate
   * @returns Promise containing the activation result
   */
  public async activate(data: { job: JobData }): Promise<{
    activationTime?: string;
    jobId: string;
    message: string;
    plantId?: string;
    reminderPeriod?: string;
    success: boolean;
  }> {
    try {
      const { job } = data;
      const plantData = job.plant; // For onDemand jobs, this contains the plant data
      // Generate a reminder name based on job ID and plant ID if available
      const reminderName = plantData
        ? `job-reminder-${job.id}-plant-${plantData.id}`
        : `job-reminder-${job.id}`;
      // Set up the job data
      const reminderJob: ReminderJob = {
        jobId: job.id,
        payload: {
          appId: job.appId,
          id: job.id,
          path: job.path,
          plant: plantData
            ? {
                id: plantData.id,
                params: plantData.params ?? {},
              }
            : undefined,
          service: job.service,
          type: job.type,
        },
      };
      // Calculate due time from schedule instead of starting immediately
      let dueTime: string;
      let periodIso: string | undefined;

      if (plantData?.schedule?.cronExpression) {
        const cronResult = parseCronExpression(
          plantData.schedule.cronExpression,
        );

        dueTime = cronResult ? cronResult.dueTimeIso : new Date().toISOString();
        periodIso = cronResult ? cronResult.periodIso : 'PT15M'; // Default fallback
      } else if (job.defaultSchedule?.cronExpression) {
        const cronResult = parseCronExpression(
          job.defaultSchedule.cronExpression,
        );
        dueTime = cronResult ? cronResult.dueTimeIso : new Date().toISOString();
        periodIso = cronResult ? cronResult.periodIso : 'PT15M'; // Default fallback
      } else {
        // No cron schedule, start immediately with interval
        dueTime = new Date().toISOString();
        const intervalMinutes =
          plantData?.interval ?? job.defaultInterval ?? 15;
        periodIso = `PT${intervalMinutes}M`;
      }
      await this.armReminder(reminderName, reminderJob, dueTime, periodIso);

      const logMessage = plantData
        ? `Successfully activated job: ${job.id} for plant ${plantData.id}`
        : `Successfully activated job: ${job.id}`;
      return {
        activationTime: new Date().toISOString(),
        jobId: job.id,
        message: logMessage,
        plantId: plantData?.id?.toString(),
        reminderPeriod: periodIso ?? 'one-time',
        success: true,
      };
    } catch (error) {
      const errorMessage = data.job.plant
        ? `Failed to activate job: ${data.job.id} for plant ${data.job.plant.id}`
        : `Failed to activate job: ${data.job.id}`;

      JobActor.appLogger().error(`[JobActor] ${errorMessage}`, error);
      return {
        jobId: data.job.id,
        message: `${errorMessage}: ${error.message}`,
        plantId: data.job.plant?.id?.toString(),
        success: false,
      };
    }
  }

  /**
   * Stop a job by removing its reminder
   * @param data The data containing job information
   * @param data.job The job to stop
   * @returns Promise containing the stop result
   */
  public async stop(data: { job: JobData }): Promise<{
    jobId: string;
    message: string;
    plantId?: string;
    success: boolean;
  }> {
    try {
      const { job } = data;
      const plantData = job.plant; // For onDemand jobs, this contains the plant data
      // Generate the reminder name to stop
      const reminderName = plantData
        ? `job-reminder-${job.id}-plant-${plantData.id}`
        : `job-reminder-${job.id}`;
      await this.disarmReminder(reminderName);

      const logMessage = plantData
        ? `Successfully stopped job: ${job.id} for plant ${plantData.id}`
        : `Successfully stopped job: ${job.id}`;
      return {
        jobId: job.id,
        message: logMessage,
        plantId: plantData?.id?.toString(),
        success: true,
      };
    } catch (error) {
      const errorMessage = data.job.plant
        ? `Failed to stop job: ${data.job.id} for plant ${data.job.plant.id}`
        : `Failed to stop job: ${data.job.id}`;
      JobActor.appLogger().error(`[JobActor] ${errorMessage}`, error);
      return {
        jobId: data.job.id,
        message: `${errorMessage}: ${error.message}`,
        plantId: data.job.plant?.id?.toString(),
        success: false,
      };
    }
  }

  /**
   * Reschedule a job by updating its reminder
   * @param data The data containing job information
   * @param data.job The job to reschedule
   * @returns Promise containing the reschedule result
   */
  public async reschedule(data: { job: JobData }): Promise<{
    jobId: string;
    message: string;
    plantId?: string;
    success: boolean;
  }> {
    const context: JobsLogContext = {
      method: 'armReminder',
      service: 'reschedule',
    };
    try {
      const { job } = data;
      const plantData = job.plant; // For onDemand jobs, this contains the plant data

      // Generate the reminder name
      const reminderName = plantData
        ? `job-reminder-${job.id}-plant-${plantData.id}`
        : `job-reminder-${job.id}`;

      // First disarm the existing reminder
      await this.disarmReminder(reminderName);

      // Set up the job data
      const reminderJob: ReminderJob = {
        jobId: job.id,
        payload: {
          appId: job.appId,
          id: job.id,
          path: job.path,
          plant: plantData
            ? {
                id: plantData.id,
                params: plantData.params ?? {},
                schedule: plantData.schedule,
              }
            : undefined,
          service: job.service,
          type: job.type,
        },
      };
      // Calculate due time and period from new schedule
      let dueTime: string;
      let periodIso: string | undefined;

      // Determine which cron expression to use
      const cronExpression =
        plantData?.schedule?.cronExpression ??
        job.defaultSchedule?.cronExpression;

      // Parse cron if available
      const cronResult = cronExpression
        ? parseCronExpression(cronExpression)
        : null;

      if (cronResult) {
        dueTime = cronResult.dueTimeIso;
        periodIso = cronResult.periodIso;
      } else if (cronExpression) {
        // Cron parsing failed, fallback to defaults
        dueTime = new Date().toISOString();
        periodIso = 'PT15M';
      } else {
        // No cron schedule, use interval
        dueTime = new Date().toISOString();
        const intervalMinutes =
          plantData?.interval ?? job.defaultInterval ?? 60;
        periodIso = `PT${intervalMinutes}M`;
      }

      // Arm the reminder with new schedule
      await this.armReminder(reminderName, reminderJob, dueTime, periodIso);

      const logMessage = plantData
        ? `Successfully rescheduled job: ${job.id} for plant ${plantData.id}`
        : `Successfully rescheduled job: ${job.id}`;

      JobActor.appLogger().debug(`[JobActor] ${logMessage}`, context);

      return {
        jobId: job.id,
        message: logMessage,
        plantId: plantData?.id?.toString(),
        success: true,
      };
    } catch (error) {
      const errorMessage = data.job.plant
        ? `Failed to reschedule job: ${data.job.id} for plant ${data.job.plant.id}`
        : `Failed to reschedule job: ${data.job.id}`;
      JobActor.appLogger().error(`[JobActor] ${errorMessage}`, error);
      return {
        jobId: data.job.id,
        message: `${errorMessage}: ${error.message}`,
        plantId: data.job.plant?.id?.toString(),
        success: false,
      };
    }
  }

  private async updateJobState(
    jobId: string,
    plantId: string,
    status: string,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'updateJobState',
      service: 'JobActor',
    };
    if (jobId.startsWith(this.prefix)) {
      return;
    }

    const containerService = JobActor.getContainer();
    const jobContainer = containerService.getContainerJobsDefinition;

    try {
      await jobContainer.item(jobId, jobId).patch([
        {
          op: 'replace',
          path: `/plants/${plantId}/status`,
          value: status,
        },
      ]);
    } catch (error) {
      JobActor.appLogger().error(
        `Failed to update job "${jobId}":`,
        context,
        error,
      );
    }
  }
}

import { Container } from '@azure/cosmos';
import { JobsLogContext } from '@mesx/common-lib';
import { ReminderJob } from '../interfaces/reminder-job.interface';
import { ActorServiceLocator } from '../services/actor-service-locator';
import { AppLogger } from '@/common/logger/app-logger';

/**
 * Interface for job execution history data
 */
export interface JobExecutionHistory {
  id?: string;
  jobId: string;
  plantId?: string;
  [key: string]: unknown; // For additional properties
}

/**
 * Get the shared Cosmos DB container for job execution history
 * Uses the container from ActorServiceLocator to avoid creating new clients
 * @returns A Cosmos DB container instance
 */
function getJobExecutionHistoryContainer(): Container {
  const containerService = ActorServiceLocator.getInstance().getContainer();
  return containerService.getContainerJobsExecutionsHistory;
}

/**
 * Save job execution history to Cosmos DB using shared container
 * @param executionHistory The execution history object to save
 */
export async function saveToCosmosDatabase(
  executionHistory: JobExecutionHistory,
): Promise<void> {
  try {
    // Generate a unique ID if not provided
    let historyToSave = { ...executionHistory };
    if (!historyToSave.id) {
      const timestamp = new Date().toISOString().replaceAll(/[.:]/g, '-');
      const plantSuffix = historyToSave.plantId
        ? `-${historyToSave.plantId}`
        : '';
      const execId = `exec-${timestamp}-${historyToSave.jobId}${plantSuffix}`;
      historyToSave = {
        ...historyToSave,
        id: execId,
      };
    }
    // Use shared container from ActorServiceLocator
    const container = getJobExecutionHistoryContainer();
    await container.items.create(historyToSave);
  } catch (error) {
    // Use logger instead of console
    const logger = ActorServiceLocator.getInstance().getAppLogger();
    logger.error(`[CosmosDB] Failed to save execution history: ${error}`, {
      method: 'saveToCosmosDatabase',
      service: 'cosmos-database.util',
    });
    throw error;
  }
}
/**
 * Logs the execution details of a reminder job and saves them to Cosmos DB.
 *
 * This function records metadata such as duration, status, response, and errors
 * related to the execution of a specific job. It can optionally use a provided
 * logger to output messages for monitoring and debugging purposes.
 * @param job - The reminder job instance containing job metadata and identifiers.
 * @param duration - The execution time of the job in milliseconds.
 * @param status - The final result of the job execution ('success' or 'failure').
 * @param statusCode - The HTTP or process status code returned by the job.
 * @param appLogger - Optional logger object for writing logs.
 * @param appLogger.log - Function to write general log messages.
 * @param appLogger.error - Function to write error log messages.
 * @param responseBody - Optional response data returned from the job, if available.
 * @param errorMessage - Optional error message describing the failure reason.
 * @returns A promise that resolves when the log entry
 *          has been successfully written to Cosmos DB.
 */
export async function logJobExecution(
  job: ReminderJob,
  duration: number,
  status: 'success' | 'failure',
  statusCode: number,
  appLogger: AppLogger,
  responseBody?: Record<string, unknown>,
  errorMessage?: string | null,
): Promise<void> {
  const context: JobsLogContext = {
    method: 'logJobExecution',
    service: 'helper',
  };
  const { id, service, path, plant } = job.payload;
  const prefix = 'executeJobImmediately_';
  const cleanId = id.startsWith(prefix) ? id.slice(prefix.length) : id;
  const actorId = plant ? `${id}-${plant.id}` : service;
  const plantIdString = plant?.id?.toString() ?? '';
  const pathJob = path.replaceAll(':plant', plantIdString);

  const historyRecord: JobExecutionHistory = {
    actorId,
    duration,
    error: errorMessage,
    jobId: cleanId,
    plantId: plant?.id?.toString(),
    request: {
      method: 'POST',
      path: pathJob,
      payload: plant?.params ?? {},
    },
    response: responseBody ? { body: responseBody, statusCode } : undefined,
    status,
    statusCode,
    timestamp: new Date().toISOString(),
    ttl: 604_800,
  };
  try {
    await saveToCosmosDatabase(historyRecord);
  } catch (cosmosError) {
    appLogger.error(
      `[ReminderActor] Failed to save execution history to Cosmos DB: ${cosmosError}`,
      context,
      cosmosError,
    );
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { ReminderJob } from '../interfaces/reminder-job.interface';
import { AppLogger } from '@/common/logger/app-logger';

/**
 * Parses raw job data into a `ReminderJob` object.
 *
 * This function attempts to safely convert unknown or stringified input data
 * into a `ReminderJob` instance. If the input is a JSON string, it will be
 * parsed; if it's already an object, it will be cast directly.
 * In case of a parsing failure, an error is logged using the provided logger
 * and the function returns `undefined`.
 * @param data - The raw job data to be parsed (stringified JSON or object).
 * @param logger - Application logger used to record parsing errors.
 * @returns A parsed `ReminderJob` object if successful,
 *          otherwise `undefined` when the input is invalid or parsing fails.
 */
export function parseJobData(
  data: unknown,
  logger: AppLogger,
): ReminderJob | undefined {
  const context: JobsLogContext = {
    method: 'armReminder',
    service: 'JobActor',
  };
  if (typeof data === 'string') {
    try {
      return JSON.parse(data) as ReminderJob;
    } catch (parseError) {
      logger.error(
        `[ReminderJobParser] Failed to parse job data as JSON: ${parseError}`,
        context,
        parseError,
      );
      return undefined;
    }
  } else if (typeof data === 'object' && data !== undefined) {
    return data as ReminderJob;
  }

  return undefined;
}

