@Controller('jobs')
export class JobsController {
  public constructor(
    private readonly reminderScheduler: ReminderSchedulerService,
    private readonly logger: AppLogger,
  ) {}

  /**
   * Convert cron expression to ISO 8601 duration - simplified version of JobActor's cronToIso
   * This is a basic implementation that handles common patterns
   * @param cronExpression The cron expression to convert
   * @returns ISO 8601 duration string or undefined if parsing fails
   */
  private cronToIso(cronExpression: string): string | undefined {
    const context: JobsLogContext = {
      method: 'cronToIso',
      service: 'JobsController',
    };
    try {
      const parts = cronExpression.split(' ');
      if (parts.length !== 5) {
        this.logger.warn(
          `Invalid cron expression format: ${cronExpression}`,
          context,
        );
        return undefined; // Don't use default, return undefined
      }

      const [minute, hour, day, month] = parts;

      // Every X minutes: */X * * * *
      if (
        minute.startsWith('*/') &&
        hour === '*' &&
        day === '*' &&
        month === '*'
      ) {
        const intervalMinutes = Number.parseInt(minute.slice(2), 10);
        if (!Number.isNaN(intervalMinutes) && intervalMinutes > 0) {
          return `PT${intervalMinutes}M`;
        }
      }

      // Every X hours: 0 */X * * *
      if (
        /^\d+$/.test(minute) &&
        hour.startsWith('*/') &&
        day === '*' &&
        month === '*'
      ) {
        const intervalHours = Number.parseInt(hour.slice(2), 10);
        if (!Number.isNaN(intervalHours) && intervalHours > 0) {
          return `PT${intervalHours}H`;
        }
      }

      // Daily at specific time: M H * * *
      if (
        /^\d+$/.test(minute) &&
        /^\d+$/.test(hour) &&
        day === '*' &&
        month === '*'
      ) {
        return 'PT24H';
      }

      // Hourly at specific minute: M * * * *
      if (
        /^\d+$/.test(minute) &&
        hour === '*' &&
        day === '*' &&
        month === '*'
      ) {
        return 'PT1H';
      }

      // No default fallback, return undefined if we can't parse the expression
      return undefined;
    } catch (error) {
      this.logger.error(
        `Error parsing cron expression: ${cronExpression}`,
        context,
        error,
      );
      return undefined; // Return undefined instead of default value
    }
  }

  @Post('activate')
  public async activateJob(
    @Body() request: JobPlantActivationRequest,
  ): Promise<JobOperationResponse> {
    const { job, plantId } = request;

    // If no plantId is specified but the job type is onDemand, we need a plantId
    if (!plantId && job.type === JOB_TYPE.ON_DEMAND) {
      return {
        jobId: job.id,
        message: 'For onDemand jobs, a plantId must be specified',
        success: false,
      };
    }

    // For required jobs with no plantId specified, activate all plants
    if (!plantId && job.type === JOB_TYPE.REQUIRED) {
      return this.activateAllPlants(job);
    }

    // Otherwise, activate the specific plant
    // PlantId must be defined at this point
    return this.activatePlant(job, plantId as number);
  }

  /**
   * Activate a job for a specific plant
   * @param job - The job configuration to activate
   * @param plantId - The ID of the plant to activate the job for
   * @returns Operation response indicating success or failure
   */
  private async activatePlant(
    job: JobDto,
    plantId: number,
  ): Promise<JobOperationResponse> {
    const context: JobsLogContext = {
      method: 'activatePlant',
      service: 'JobsController',
    };
    // Find the plant in the job
    const plant = job.plants.find((p: PlantConfigDto) => p.id === plantId);

    if (!plant) {
      return {
        jobId: job.id,
        message: `Plant ${plantId} not found in job ${job.id}`,
        plantId,
        success: false,
      };
    }

    const actorId = `${job.id}-${plantId}`;
    const reminderName = `job-reminder-${job.id}-${plantId}`;
    try {
      // Convert job scheduler format to reminder job format
      const reminderJob: ReminderJob = {
        jobId: job.id,
        metadata: {
          activatedAt: new Date().toISOString(),
          jobType: job.type,
          plantId: plant.id.toString(),
        },
        payload: {
          appId: job.appId,
          defaultInterval: job.defaultInterval,
          defaultSchedule: job.defaultSchedule,
          description: job.description,
          id: job.id,
          path: job.path,
          plant: {
            id: plant.id,
            params: plant.params as unknown as Record<string, unknown>,
          },
          service: job.service,
          type: job.type,
        },
      };

      // Calculate due time and period from schedule (use plant schedule if available, otherwise use default)
      let dueTimeIso: string;
      let periodIso: string | undefined;

      const schedule = plant.schedule ?? job.defaultSchedule;
      const interval = plant.interval ?? job.defaultInterval;

      if (schedule?.scheduledAt) {
        // One-time job
        dueTimeIso = schedule.scheduledAt;
      } else if (schedule?.cronExpression) {
        // Cron-based job: calculate proper due time and period
        this.logger.debug(
          `Processing cron expression: ${schedule.cronExpression}`,
          context,
        );

        // Validate cron expression
        if (isValidCronExpression(schedule.cronExpression)) {
          // Parse cron expression for next execution time
          const cronResult = parseCronExpression(schedule.cronExpression);
          if (cronResult) {
            dueTimeIso = cronResult.dueTimeIso;
            this.logger.debug(
              `Next cron execution calculated: ${dueTimeIso}`,
              context,
            );
          } else {
            // Fail if parsing is unsuccessful - no fallbacks
            throw new Error(
              `Failed to parse cron expression: ${schedule.cronExpression}`,
            );
          }

          // Calculate period using the cron-to-ISO conversion
          periodIso = this.cronToIso(schedule.cronExpression);
          if (!periodIso) {
            throw new Error(
              `Unable to calculate period for cron expression: ${schedule.cronExpression}`,
            );
          }
        } else {
          this.logger.warn(
            `Invalid cron expression: ${schedule.cronExpression}`,
            context,
          );
          throw new Error(
            `Invalid cron expression: ${schedule.cronExpression}`,
          );
        }
      } else if (interval) {
        // Interval-based job (convert minutes to milliseconds)
        dueTimeIso = new Date(Date.now() + interval * 60_000).toISOString();
        periodIso = `PT${interval * 60}S`; // ISO 8601 duration format (seconds)
      } else {
        // No schedule or interval provided
        throw new Error(
          `No valid schedule or interval provided for job ${job.id} and plant ${plantId}`,
        );
      }

      // Activate the reminder using existing reminder system
      await this.reminderScheduler.armReminder(
        actorId,
        reminderName,
        reminderJob,
        dueTimeIso,
        periodIso,
      );

      this.logger.debug(
        `Successfully activated job: ${job.id} for plant: ${plantId}`,
        context,
      );

      return {
        jobId: job.id,
        message: `Job ${job.id} activated successfully for plant ${plantId}`,
        plantId,
        success: true,
      };
    } catch (error) {
      this.logger.error(
        `Failed to activate job: ${job.id} for plant: ${plantId}`,
        error,
      );
      return {
        jobId: job.id,
        message: `Failed to activate job: ${error.message}`,
        plantId,
        success: false,
      };
    }
  }

  /**
   * Activate a job for all plants (required job type)
   * @param job - The job configuration to activate for all plants
   * @returns Operation response indicating success or failure for all plants
   */
  private async activateAllPlants(job: JobDto): Promise<JobOperationResponse> {
    const results = [];
    let overallSuccess = true;

    // Process all plants in parallel to avoid sequential await in loop
    const plantResults = await Promise.all(
      job.plants.map((plant) => this.activatePlant(job, plant.id)),
    );

    // Process results
    for (const result of plantResults) {
      results.push(result);
      if (!result.success) {
        overallSuccess = false;
      }
    }

    if (overallSuccess) {
      return {
        data: { results },
        jobId: job.id,
        message: `Job ${job.id} activated successfully for all plants`,
        success: true,
      };
    }
    return {
      data: { results },
      jobId: job.id,
      message: `Failed to activate job ${job.id} for some plants`,
      success: false,
    };
  }

  /**
   * Stop a running job for a specific plant
   * @param request - The job and plant information to stop
   * @returns Operation response indicating success or failure
   */
  @Post('stop')
  public async stopJob(
    @Body() request: JobPlantActivationRequest,
  ): Promise<JobOperationResponse> {
    const context: JobsLogContext = {
      method: 'stopJob',
      service: 'JobsController',
    };
    const { job, plantId } = request;

    if (!plantId) {
      return {
        jobId: job.id,
        message: 'A plantId must be specified to stop a job',
        success: false,
      };
    }

    // Find the plant in the job
    const plant = job.plants.find((p: PlantConfigDto) => p.id === plantId);

    if (!plant) {
      return {
        jobId: job.id,
        message: `Plant ${plantId} not found in job ${job.id}`,
        plantId,
        success: false,
      };
    }

    const actorId = `${job.id}-${plantId}`;
    const reminderName = `job-reminder-${job.id}-${plantId}`;
    try {
      // Disarm the reminder using existing reminder system
      await this.reminderScheduler.disarmReminder(actorId, reminderName);

      this.logger.debug(
        `Successfully stopped job: ${job.id} for plant: ${plantId}`,
        context,
      );

      return {
        jobId: job.id,
        message: `Job ${job.id} stopped successfully for plant ${plantId}`,
        plantId,
        success: true,
      };
    } catch (error) {
      this.logger.error(
        `Failed to stop job: ${job.id} for plant: ${plantId}`,
        context,
        error,
      );
      return {
        jobId: job.id,
        message: `Failed to stop job: ${error.message}`,
        plantId,
        success: false,
      };
    }
  }

  /**
   * Reschedule a running job for a specific plant
   * @param request - The job and plant information to reschedule
   * @returns Operation response indicating success or failure
   */
  @Post('reschedule')
  public async rescheduleJob(
    @Body() request: JobPlantActivationRequest,
  ): Promise<JobOperationResponse> {
    const context: JobsLogContext = {
      method: 'rescheduleJob',
      service: 'JobsController',
    };
    const { job, plantId } = request;

    if (!plantId) {
      return {
        jobId: job.id,
        message: 'A plantId must be specified to reschedule a job',
        success: false,
      };
    }

    // Find the plant in the job
    const plant = job.plants.find((p: PlantConfigDto) => p.id === plantId);

    if (!plant) {
      return {
        jobId: job.id,
        message: `Plant ${plantId} not found in job ${job.id}`,
        plantId,
        success: false,
      };
    }

    const actorId = `${job.id}-${plantId}`;
    const reminderName = `job-reminder-${job.id}-${plantId}`;
    try {
      // First, stop the existing reminder
      await this.reminderScheduler.disarmReminder(actorId, reminderName);

      // Then reactivate with new schedule
      const activationResult = await this.activatePlant(job, plantId);

      if (activationResult.success) {
        this.logger.debug(
          `Successfully rescheduled job: ${job.id} for plant: ${plantId}`,
          context,
        );
        return {
          jobId: job.id,
          message: `Job ${job.id} rescheduled successfully for plant ${plantId}`,
          plantId,
          success: true,
        };
      }
      throw new Error(activationResult.message);
    } catch (error) {
      this.logger.error(
        `Failed to reschedule job: ${job.id} for plant: ${plantId}`,
        context,
        error,
      );
      return {
        jobId: job.id,
        message: `Failed to reschedule job: ${error.message}`,
        plantId,
        success: false,
      };
    }
  }
}

