import { ReminderSchedulerService } from './services/reminder-scheduler.service';

@Module({
  controllers: [JobsController],
  providers: [ReminderSchedulerService],
})
export class ReminderSchedulerModule {}

// ReminderSchedulerService proxies calls to ReminderActorService via Dapr ActorProxyBuilder.
import { ActorProxyBuilder, ActorId, DaprClient } from '@dapr/dapr';
import { Injectable, Logger, OnModuleDestroy } from '@nestjs/common';
import { ReminderJob } from '../../actor/interfaces/reminder-job.interface';
import { ActorReminderInterface } from '../../actor/interfaces/reminder.interface';
import { JobActor } from '../../actor/services/reminder-actor.service';

@Injectable()
export class ReminderSchedulerService implements OnModuleDestroy {
  private readonly logger = new Logger(ReminderSchedulerService.name);

  private readonly client: DaprClient;

  private readonly builder: ActorProxyBuilder<ActorReminderInterface>;

  public constructor() {
    this.client = new DaprClient();
    this.builder = new ActorProxyBuilder<ActorReminderInterface>(
      JobActor,
      this.client,
    );
  }

  public async onModuleDestroy(): Promise<void> {
    this.logger.debug('ReminderSchedulerService cleanup started');

    try {
      // Clean up DaprClient resources
      // Note: DaprClient doesn't have an explicit close/dispose method
      // But we can check for any cleanup methods that might exist

      // Check if the client has a stop or close method
      const clientWithStop = this.client as unknown as {
        stop?: () => Promise<void>;
      };

      if (clientWithStop.stop && typeof clientWithStop.stop === 'function') {
        await clientWithStop.stop();
        this.logger.debug('DaprClient stopped successfully');
      }

      // Note: Since client and builder are readonly, they will be garbage collected
      // When the service instance is destroyed by NestJS dependency injection

      this.logger.debug('ReminderSchedulerService cleanup completed');
    } catch (error) {
      this.logger.error('Error during ReminderSchedulerService cleanup', error);
      // Don't throw - allow graceful degradation during shutdown
    }
  }

  public async armReminder(
    actorId: string,
    reminderName: string,
    job: ReminderJob,
    dueTimeIso: string,
    periodIso?: string,
  ): Promise<void> {
    const proxy = this.builder.build(new ActorId(actorId));

    await proxy.armReminder(reminderName, job, dueTimeIso, periodIso);
  }

  public async disarmReminder(
    actorId: string,
    reminderName: string,
  ): Promise<void> {
    const proxy = this.builder.build(new ActorId(actorId));

    await proxy.disarmReminder(reminderName);
  }

  public async testReminder(
    actorId: string,
    reminderName: string,
  ): Promise<string> {
    this.builder.build(new ActorId(actorId));

    return `Tested reminder proxy for actorId=${actorId}, reminderName=${reminderName}`;
  }
}

import { CronExpressionParser, CronDate } from 'cron-parser';

export interface CronParseResult {
  dueTimeIso: string;
  periodIso?: string;
}

/**
 * Normalize cron expression to 6 fields (add seconds if missing)
 * @param cronExpression - The cron expression to normalize
 * @returns Normalized cron expression with 6 fields
 */
function normalizeCronExpression(cronExpression: string): string {
  const trimmed = cronExpression.trim();

  // Handle predefined expressions - cron-parser supports these directly
  if (trimmed.startsWith('@')) {
    return trimmed;
  }

  const parts = trimmed.split(/\s+/);

  // If 5 fields, add seconds field at the beginning (0 = start of minute)
  if (parts.length === 5) {
    return `0 ${trimmed}`;
  }

  // If already 6 fields, return as is
  if (parts.length === 6) {
    return trimmed;
  }

  throw new Error(
    `Invalid cron expression format: ${trimmed}. Expected 5 or 6 fields.`,
  );
}

/**
 * Convert milliseconds to ISO 8601 period format
 * @param milliseconds - The duration in milliseconds
 * @returns ISO 8601 period string (e.g., "PT1H30M" for 1 hour 30 minutes)
 */
function convertMillisecondsToPeriod(milliseconds: number): string {
  if (milliseconds <= 0) {
    return 'PT0S';
  }

  const seconds = Math.floor(milliseconds / 1000);
  const minutes = Math.floor(seconds / 60);
  const hours = Math.floor(minutes / 60);
  const days = Math.floor(hours / 24);
  const weeks = Math.floor(days / 7);

  let result = 'P';

  // Add time components
  if (weeks > 0) {
    result += `${weeks}W`;
  } else {
    if (days > 0) {
      result += `${days}D`;
    }

    const remainingHours = hours % 24;
    const remainingMinutes = minutes % 60;
    const remainingSeconds = seconds % 60;

    if (remainingHours > 0 || remainingMinutes > 0 || remainingSeconds > 0) {
      result += 'T';

      if (remainingHours > 0) {
        result += `${remainingHours}H`;
      }
      if (remainingMinutes > 0) {
        result += `${remainingMinutes}M`;
      }
      if (remainingSeconds > 0) {
        result += `${remainingSeconds}S`;
      }
    }
  }

  return result === 'P' ? 'PT0S' : result;
}

/**
 * Parse a cron expression to extract the next execution time and period for DAPR actor reminders
 * @param cronExpression - The cron expression to parse (supports both 5 and 6 field formats)
 * @returns Object containing dueTimeIso and periodIso, or undefined if parsing fails
 */
export function parseCronExpression(
  cronExpression: string,
): CronParseResult | undefined {
  try {
    // Normalize cron expression to 6 fields if needed
    const normalizedExpression = normalizeCronExpression(cronExpression);

    const interval = CronExpressionParser.parse(normalizedExpression);

    // Get the next execution time
    const nextDate: CronDate = interval.next();
    const dueTimeIso = nextDate.toISOString();

    if (!dueTimeIso) {
      console.error('Failed to get ISO string from next execution date');
      return undefined;
    }

    // Calculate period by getting the difference between next two executions
    const followingDate: CronDate = interval.next();
    const periodMs: number = followingDate.getTime() - nextDate.getTime();
    const periodIso: string = convertMillisecondsToPeriod(periodMs);

    return {
      dueTimeIso,
      periodIso,
    };
  } catch (error) {
    console.error('Failed to parse cron expression:', cronExpression, error);
    return undefined;
  }
}

/**
 * Validate if a cron expression is valid using cron-parser
 * @param cronExpression - The cron expression to validate
 * @returns true if valid, false otherwise
 */
export function isValidCronExpression(cronExpression: string): boolean {
  try {
    const normalizedExpression = normalizeCronExpression(cronExpression);
    CronExpressionParser.parse(normalizedExpression);
    return true;
  } catch {
    return false;
  }
}

